// TestShell sends POST /api/node/{hostname}/command/shell and checks each
// answer's response.
func (s *APIShellPublicTestSuite) TestShell() {
	s.api.Run(s.T(), []servertest.Case{
		{
			Name: "when the example \"A pipe\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
				servertest.Completed("server1", `{"stdout":"HELLO\n","stderr":"","exit_code":0,"duration_ms":0,"changed":true}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":true,"duration_ms":0,"exit_code":0,"hostname":"server1","status":"ok","stderr":"","stdout":"HELLO\n"}]}`,
		},
		{
			Name: "when the example \"A pipe\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/_all/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"_all",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
				servertest.Completed("server1", `{"stdout":"HELLO\n","stderr":"","exit_code":0,"duration_ms":0,"changed":true}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":true,"duration_ms":0,"exit_code":0,"hostname":"server1","status":"ok","stderr":"","stdout":"HELLO\n"},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the example \"A command line that exits non-zero\" is sent, the host's result is returned",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/command/shell",
				Body:   `{"command":"exit 3"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"command.shell",
				command.ShellInput{Command: "exit 3"},
				servertest.Completed("server1", `{"stdout":"","stderr":"","exit_code":3,"duration_ms":0,"changed":true}`),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":true,"duration_ms":0,"exit_code":3,"hostname":"server1","status":"ok","stderr":"","stdout":""}]}`,
		},
		{
			Name: "when the example \"A command line that exits non-zero\" is broadcast, every host's result is returned",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/_all/command/shell",
				Body:   `{"command":"exit 3"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"_all",
				"command.shell",
				command.ShellInput{Command: "exit 3"},
				servertest.Completed("server1", `{"stdout":"","stderr":"","exit_code":3,"duration_ms":0,"changed":true}`),
				servertest.Skipped("server2"),
				servertest.Failed("server3", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"changed":true,"duration_ms":0,"exit_code":3,"hostname":"server1","status":"ok","stderr":"","stdout":""},{"error":"unsupported","hostname":"server2","status":"skipped"},{"error":"boom","hostname":"server3","status":"failed"}]}`,
		},
		{
			Name: "when the host skips it, its row says skipped",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
				servertest.Skipped("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"unsupported","hostname":"server1","status":"skipped"}]}`,
		},
		{
			Name: "when the host fails it, its row says failed",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
				servertest.Failed("server1", "boom"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"boom","hostname":"server1","status":"failed"}]}`,
		},
		{
			Name: "when the host never answers, its row says timeout",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
				servertest.TimedOut("server1"),
			),
			WantCode: http.StatusOK,
			WantBody: `{"job_id":"job-1","results":[{"error":"","hostname":"server1","status":"timeout"}]}`,
		},
		{
			Name: "when the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/server1/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"server1",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
		{
			Name: "when broadcast and the job client fails, it is a 500",
			Request: servertest.Request{
				Method: http.MethodPost,
				Path:   "/api/node/_all/command/shell",
				Body:   `{"command":"echo hello | tr a-z A-Z"}`,
			},
			Token: servertest.Admin,
			Job: servertest.Modify(
				"_all",
				"command.shell",
				command.ShellInput{Command: "echo hello | tr a-z A-Z"},
			).Fails(servertest.ErrUnreachable),
			WantCode: http.StatusInternalServerError,
		},
	})
}

